function Logo({ compact = false, inverse = false }: { compact?: boolean; inverse?: boolean }) {
  const asset = compact ? (inverse ? "/juro-mark-light" : "/juro-mark") : inverse ? "/juro-logo-light" : "/juro-logo-primary";
  return <div className={`brand ${compact ? "brand-compact" : ""} ${inverse ? "brand-inverse" : ""}`} aria-label="JURO — Юрист в кармане">
    <img className="brand-logo" src={`${asset}.png`} alt="JURO" decoding="async"/>
  </div>;
}

type AgentState = "idle" | "listening" | "thinking" | "speaking" | "muted";

function AgentPortrait({ className = "", state = "idle", showStatus = false, eager = false }: { className?: string; state?: AgentState; showStatus?: boolean; eager?: boolean }) {
  const trackPointer = (event: React.PointerEvent<HTMLSpanElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    const x = ((event.clientX - box.left) / box.width - 0.5) * 2;
    const y = ((event.clientY - box.top) / box.height - 0.5) * 2;
    event.currentTarget.style.setProperty("--look-x", `${x * 4}deg`);
    event.currentTarget.style.setProperty("--look-y", `${y * -3}deg`);
  };
  const resetPointer = (event: React.PointerEvent<HTMLSpanElement>) => {
    event.currentTarget.style.setProperty("--look-x", "0deg");
    event.currentTarget.style.setProperty("--look-y", "0deg");
  };
  const status = state === "speaking" ? "Юробек отвечает" : state === "thinking" ? "Юробек анализирует" : state === "muted" ? "Микрофон выключен" : "Юробек слушает";
  return <span className={`jurobek-live state-${state} ${className}`} onPointerMove={trackPointer} onPointerLeave={resetPointer}>
    <span className="jurobek-figure">
      <picture>
        <source srcSet="/jurobek-avatar.webp" type="image/webp"/>
        <img className="jurobek-portrait" src="/jurobek-avatar.png" alt="AI-аватар Юробек" loading={eager ? "eager" : "lazy"} fetchPriority={eager ? "high" : "auto"} decoding="async" draggable={false}/>
      </picture>
      <span className="jurobek-blink" aria-hidden="true"/>
      <span className="jurobek-mouth" aria-hidden="true"/>
    </span>
    {showStatus && <span className="jurobek-status"><i/>{status}</span>}
  </span>;
}

function Button({ children, onClick, kind = "primary", icon: Icon, type = "button", disabled = false, className = "" }: { children: React.ReactNode; onClick?: () => void; kind?: "primary" | "secondary" | "ghost" | "danger"; icon?: typeof Home; type?: "button" | "submit"; disabled?: boolean; className?: string }) {
  return <button type={type} className={`btn btn-${kind} ${className}`} onClick={onClick} disabled={disabled}>{Icon && <Icon size={17}/>}<span>{children}</span></button>;
}

function Field({ label, type = "text", placeholder, required = false }: { label: string; type?: string; placeholder?: string; required?: boolean }) {
  const [visible, setVisible] = useState(false);
  const password = type === "password";
  return <label className="field"><span>{label}</span><div className="input-wrap"><input required={required} type={password && visible ? "text" : type} placeholder={placeholder}/>{password && <button type="button" aria-label={visible ? "Скрыть пароль" : "Показать пароль"} onClick={() => setVisible(!visible)}>{visible ? <EyeOff size={17}/> : <Eye size={17}/>}</button>}</div></label>;
}

function RiskBadge({ level, children }: { level: "high" | "medium" | "low" | "info"; children: React.ReactNode }) {
  const icons = { high: AlertCircle, medium: Clock3, low: CheckCircle2, info: CircleHelp };
  const Icon = icons[level];
  return <span className={`risk risk-${level}`}><Icon size={14}/>{children}</span>;
}

function Toasts({ items }: { items: ToastState[] }) {
  return <div className="toasts" aria-live="polite"><AnimatePresence>{items.map(item => <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0}} className="toast" key={item.id}><CheckCircle2 size={18}/>{item.text}</motion.div>)}</AnimatePresence></div>;
}

export function JuroLanding() {
  const [lang, setLang] = useState<Lang>("ru");
  useEffect(() => {
    const saved = localStorage.getItem("juro-lang") as Lang | null;
    if (saved === "ru" || saved === "uz") setLang(saved);
  }, []);
  const toggleLang = () => {
    const next = lang === "ru" ? "uz" : "ru";
    setLang(next);
    localStorage.setItem("juro-lang", next);
  };
  const openApp = (next: Route) => {
    const view = next === "login" ? "login" : "register";
    window.location.assign(`https://app.juro.uz/?view=${view}`);
  };
  return <Landing go={openApp} lang={lang} toggleLang={toggleLang}/>;
}

export default function JuroApp() {
  const [route, setRoute] = useState<Route>("login");
  const [lang, setLang] = useState<Lang>("ru");
  const [mobileMenu, setMobileMenu] = useState(false);
  const [toasts, setToasts] = useState<ToastState[]>([]);
  const [modal, setModal] = useState<string | null>(null);
  const [authenticated, setAuthenticated] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const t = copy[lang];
  useEffect(() => { document.documentElement.lang = lang === "ru" ? "ru" : "uz"; }, [lang]);
  useEffect(() => {
    const saved = localStorage.getItem("juro-lang") as Lang | null;
    if (saved === "ru" || saved === "uz") setLang(saved);
    const signedIn = localStorage.getItem("juro-auth") === "true";
    setAuthenticated(signedIn);
    if (signedIn) {
      setRoute("dashboard");
      return;
    }
    const view = new URLSearchParams(window.location.search).get("view");
    setRoute(view === "register" ? "register" : "login");
  }, []);

  const notify = (text: string) => {
    const id = Date.now(); setToasts(v => [...v, { id, text }]);
    window.setTimeout(() => setToasts(v => v.filter(x => x.id !== id)), 2800);
  };
  const go = (next: Route) => {
    if (next === "landing") {
      window.location.assign("https://juro.uz");
      return;
    }
    setRoute(next); setMobileMenu(false); window.scrollTo({ top: 0, behavior: "smooth" });
  };
  const toggleLang = () => { const next = lang === "ru" ? "uz" : "ru"; setLang(next); localStorage.setItem("juro-lang", next); };
  const login = () => { setAuthenticated(true); localStorage.setItem("juro-auth", "true"); go("dashboard"); };
  const logout = () => { setAuthenticated(false); localStorage.removeItem("juro-auth"); go("login"); };

  const publicRoute = ["landing", "login", "register", "forgot", "onboarding"].includes(route);
  return <div className="juro-root">
    {publicRoute ? <PublicArea route={route} go={go} lang={lang} toggleLang={toggleLang} login={login} notify={notify}/> :
      <div className={`app-shell ${collapsed ? "shell-collapsed" : ""}`}>
        <Sidebar route={route} go={go} t={t} lang={lang} toggleLang={toggleLang} collapsed={collapsed} setCollapsed={setCollapsed} logout={logout}/>
        <div className="app-main">
          <Header t={t} go={go} toggleLang={toggleLang} onMenu={() => setMobileMenu(true)} notify={notify}/>
          <main className="screen"><Screen route={route} go={go} lang={lang} notify={notify} openModal={setModal}/></main>
          <MobileNav route={route} go={go} lang={lang}/>
        </div>
        <AnimatePresence>{mobileMenu && <MobileDrawer go={go} lang={lang} close={() => setMobileMenu(false)} toggleLang={toggleLang} logout={logout}/>}</AnimatePresence>
      </div>}
    <AnimatePresence>{modal && <Modal title={modal} close={() => setModal(null)} notify={notify}/>}</AnimatePresence>
    <Toasts items={toasts}/>
    {authenticated && publicRoute && <button className="return-chip" onClick={() => go("dashboard")}>Открыть кабинет <ArrowRight size={15}/></button>}
  </div>;
}

function PublicArea({ route, go, lang, toggleLang, login, notify }: { route: Route; go: (r: Route) => void; lang: Lang; toggleLang: () => void; login: () => void; notify: (s: string) => void }) {
  if (route === "landing") return <Landing go={go} lang={lang} toggleLang={toggleLang}/>;
  if (route === "onboarding") return <Onboarding go={go} lang={lang} notify={notify}/>;
  return <Auth route={route} go={go} lang={lang} toggleLang={toggleLang} login={login} notify={notify}/>;
}

